package ssh

import (
	"bytes"
	"fmt"
	"os"
	"strings"

	"golang.org/x/crypto/ssh"
)

type CommandRunner interface {
	RunCommand(cmd string) (string, error)
	Close() error
}

type SSHClient struct {
	config SSHClientConfig
	client *ssh.Client
}

type SSHClientConfig struct {
	Host           string
	User           string
	Port           int
	PrivateKey     string
	PrivateKeyPath string
}

func NewClient(config SSHClientConfig) *SSHClient {
	return &SSHClient{
		config: config,
	}
}

func (c *SSHClient) connect() error {
	if c.client != nil {
		return nil
	}

	var privateKeyBytes []byte
	var err error

	if c.config.PrivateKey != "" {
		privateKeyBytes = []byte(c.config.PrivateKey)
	} else if c.config.PrivateKeyPath != "" {
		privateKeyBytes, err = os.ReadFile(c.config.PrivateKeyPath)
		if err != nil {
			return fmt.Errorf("failed to read private key from path %s: %w", c.config.PrivateKeyPath, err)
		}
	} else {
		return fmt.Errorf("either private_key or private_key_path must be provided")
	}

	signer, err := ssh.ParsePrivateKey(privateKeyBytes)
	if err != nil {
		return fmt.Errorf("failed to parse private key: %w", err)
	}

	config := &ssh.ClientConfig{
		User: c.config.User,
		Auth: []ssh.AuthMethod{
			ssh.PublicKeys(signer),
		},
		HostKeyCallback: ssh.InsecureIgnoreHostKey(),
	}

	hostAddr := fmt.Sprintf("%s:%d", c.config.Host, c.config.Port)
	c.client, err = ssh.Dial("tcp", hostAddr, config)
	if err != nil {
		return fmt.Errorf("failed to connect: %w", err)
	}
	return nil
}

func (c *SSHClient) RunCommand(cmd string) (string, error) {
	if err := c.connect(); err != nil {
		return "", err
	}

	session, err := c.client.NewSession()
	if err != nil {
		return "", fmt.Errorf("failed to create session: %w", err)
	}
	defer session.Close()

	var stdout, stderr bytes.Buffer
	session.Stdout = &stdout
	session.Stderr = &stderr

	if err := session.Run(cmd); err != nil {
		return "", fmt.Errorf("command failed: %w, stderr: %s", err, stderr.String())
	}

	return strings.TrimSpace(stdout.String()), nil
}

func (c *SSHClient) Close() error {
	if c.client == nil {
		return nil
	}
	return c.client.Close()
}
