// Copyright (c) HashiCorp, Inc.
// SPDX-License-Identifier: MPL-2.0

package provider

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"strings"

	"github.com/hashicorp/terraform-plugin-framework/path"
	"github.com/hashicorp/terraform-plugin-framework/resource"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/planmodifier"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/stringplanmodifier"
	"github.com/hashicorp/terraform-plugin-framework/types"
	"github.com/hashicorp/terraform-plugin-log/tflog"
	"github.com/rsbh/terraform-provider-docker-compose/internal/ssh"
)

// Ensure provider defined types fully satisfy framework interfaces.
var _ resource.Resource = &StackResource{}
var _ resource.ResourceWithImportState = &StackResource{}

func NewStackResource() resource.Resource {
	return &StackResource{}
}

// StackResource defines the resource implementation.
type StackResource struct {
	client ssh.CommandRunner
}

// StackResourceModel describes the resource data model.
type StackResourceModel struct {
	Name              types.String `tfsdk:"name"`
	ComposeFile       types.String `tfsdk:"compose_file"`
	ComposeFileHash   types.String `tfsdk:"compose_file_hash"`
	WorkDir           types.String `tfsdk:"work_dir"`
	Id                types.String `tfsdk:"id"`
	RunningContainers types.String `tfsdk:"running_containers"`
}

func (r *StackResource) Metadata(ctx context.Context, req resource.MetadataRequest, resp *resource.MetadataResponse) {
	resp.TypeName = req.ProviderTypeName + "_stack"
}

func (r *StackResource) Schema(ctx context.Context, req resource.SchemaRequest, resp *resource.SchemaResponse) {
	resp.Schema = schema.Schema{
		// This description is used by the documentation generator and the language server.
		MarkdownDescription: "Stack resource",

		Attributes: map[string]schema.Attribute{
			"name": schema.StringAttribute{
				MarkdownDescription: "Name of the Docker Compose project",
				Required:            true,
				PlanModifiers: []planmodifier.String{
					stringplanmodifier.RequiresReplace(),
				},
			},
			"compose_file": schema.StringAttribute{
				MarkdownDescription: "Content of the Docker Compose file",
				Required:            true,
			},
			"compose_file_hash": schema.StringAttribute{
				MarkdownDescription: "Hash of the Docker Compose file",
				Computed:            true,
			},
			"work_dir": schema.StringAttribute{
				MarkdownDescription: "Working directory on remote host",
				Required:            true,
				PlanModifiers: []planmodifier.String{
					stringplanmodifier.RequiresReplace(),
				},
			},
			"id": schema.StringAttribute{
				Computed:            true,
				MarkdownDescription: "Stack identifier",
				PlanModifiers: []planmodifier.String{
					stringplanmodifier.UseStateForUnknown(),
				},
			},
			"running_containers": schema.StringAttribute{
				Computed:            true,
				MarkdownDescription: "Number of running containers",
			},
		},
	}
}

func (r *StackResource) Configure(ctx context.Context, req resource.ConfigureRequest, resp *resource.ConfigureResponse) {
	// Prevent panic if the provider has not been configured.
	if req.ProviderData == nil {
		return
	}

	client, ok := req.ProviderData.(*ssh.SSHClient)

	if !ok {
		resp.Diagnostics.AddError(
			"Unexpected Resource Configure Type",
			fmt.Sprintf("Expected *ssh.SSHClient, got: %T. Please report this issue to the provider developers.", req.ProviderData),
		)

		return
	}

	r.client = client
}

func (r *StackResource) Create(ctx context.Context, req resource.CreateRequest, resp *resource.CreateResponse) {
	var data StackResourceModel

	// Read Terraform plan data into the model
	resp.Diagnostics.Append(req.Plan.Get(ctx, &data)...)

	if resp.Diagnostics.HasError() {
		return
	}

	name := data.Name.ValueString()
	workDir := data.WorkDir.ValueString()
	composeFile := data.ComposeFile.ValueString()

	// Create working directory on remote host
	if _, err := r.client.RunCommand(fmt.Sprintf("mkdir -p %s", workDir)); err != nil {
		resp.Diagnostics.AddError("Failed to create work directory", err.Error())
		return
	}

	// Write compose file to remote host
	escapedContent := strings.ReplaceAll(composeFile, "'", "'\\''")
	if _, err := r.client.RunCommand(fmt.Sprintf("echo '%s' > %s/docker-compose.yml", escapedContent, workDir)); err != nil {
		resp.Diagnostics.AddError("Failed to write docker-compose.yml", err.Error())
		return
	}

	// Run docker compose up -d
	cmd := fmt.Sprintf("cd %s && docker compose -p %s up -d", workDir, name)
	tflog.Debug(ctx, "Running docker compose up", map[string]interface{}{"cmd": cmd})
	if _, err := r.client.RunCommand(cmd); err != nil {
		resp.Diagnostics.AddError("Failed to run docker compose up", err.Error())
		return
	}

	data.Id = types.StringValue(name)
	data.ComposeFileHash = types.StringValue(hashContent(composeFile))

	// Get running containers count
	if containers, err := r.client.RunCommand(fmt.Sprintf("docker compose -p %s ps --format json | wc -l", name)); err == nil {
		data.RunningContainers = types.StringValue(containers)
	}

	tflog.Trace(ctx, "Created stack resource")

	// Save data into Terraform state
	resp.Diagnostics.Append(resp.State.Set(ctx, &data)...)
}

func (r *StackResource) Read(ctx context.Context, req resource.ReadRequest, resp *resource.ReadResponse) {
	var data StackResourceModel

	// Read Terraform prior state data into the model
	resp.Diagnostics.Append(req.State.Get(ctx, &data)...)

	if resp.Diagnostics.HasError() {
		return
	}

	name := data.Name.ValueString()
	workDir := data.WorkDir.ValueString()

	// Check if project exists
	cmd := fmt.Sprintf("docker compose -p %s ps --format json | wc -l", name)
	containers, err := r.client.RunCommand(cmd)
	if err != nil {
		// Project doesn't exist anymore
		resp.State.RemoveResource(ctx)
		return
	}

	data.RunningContainers = types.StringValue(containers)

	// Read current compose file content
	readCmd := fmt.Sprintf("cat %s/docker-compose.yml", workDir)
	currentContent, err := r.client.RunCommand(readCmd)
	if err == nil {
		data.ComposeFileHash = types.StringValue(hashContent(currentContent))
	}

	// Save updated data into Terraform state
	resp.Diagnostics.Append(resp.State.Set(ctx, &data)...)
}

func (r *StackResource) Update(ctx context.Context, req resource.UpdateRequest, resp *resource.UpdateResponse) {
	var data StackResourceModel

	// Read Terraform plan data into the model
	resp.Diagnostics.Append(req.Plan.Get(ctx, &data)...)

	if resp.Diagnostics.HasError() {
		return
	}

	name := data.Name.ValueString()
	workDir := data.WorkDir.ValueString()
	composeFile := data.ComposeFile.ValueString()

	// Write updated compose file
	escapedContent := strings.ReplaceAll(composeFile, "'", "'\\''")
	if _, err := r.client.RunCommand(fmt.Sprintf("echo '%s' > %s/docker-compose.yml", escapedContent, workDir)); err != nil {
		resp.Diagnostics.AddError("Failed to write docker-compose.yml", err.Error())
		return
	}

	// Run docker compose up -d (will update changed services)
	cmd := fmt.Sprintf("cd %s && docker compose -p %s up -d", workDir, name)
	tflog.Debug(ctx, "Running docker compose up for update", map[string]interface{}{"cmd": cmd})
	if _, err := r.client.RunCommand(cmd); err != nil {
		resp.Diagnostics.AddError("Failed to run docker compose up", err.Error())
		return
	}

	data.ComposeFileHash = types.StringValue(hashContent(composeFile))

	// Get running containers count
	if containers, err := r.client.RunCommand(fmt.Sprintf("docker compose -p %s ps --format json | wc -l", name)); err == nil {
		data.RunningContainers = types.StringValue(containers)
	}

	// Save updated data into Terraform state
	resp.Diagnostics.Append(resp.State.Set(ctx, &data)...)
}

func (r *StackResource) Delete(ctx context.Context, req resource.DeleteRequest, resp *resource.DeleteResponse) {
	var data StackResourceModel

	// Read Terraform prior state data into the model
	resp.Diagnostics.Append(req.State.Get(ctx, &data)...)

	if resp.Diagnostics.HasError() {
		return
	}

	name := data.Name.ValueString()
	workDir := data.WorkDir.ValueString()

	// Run docker compose down
	cmd := fmt.Sprintf("cd %s && docker compose -p %s down", workDir, name)
	tflog.Debug(ctx, "Running docker compose down", map[string]interface{}{"cmd": cmd})
	if _, err := r.client.RunCommand(cmd); err != nil {
		resp.Diagnostics.AddError("Failed to run docker compose down", err.Error())
		return
	}

	// Optionally clean up compose file
	if _, err := r.client.RunCommand(fmt.Sprintf("rm -f %s/docker-compose.yml", workDir)); err != nil {
		tflog.Warn(ctx, "Failed to remove docker-compose.yml", map[string]interface{}{"error": err.Error()})
	}
}

func (r *StackResource) ImportState(ctx context.Context, req resource.ImportStateRequest, resp *resource.ImportStateResponse) {
	resource.ImportStatePassthroughID(ctx, path.Root("id"), req, resp)
}

func hashContent(content string) string {
	hash := sha256.Sum256([]byte(content))
	return hex.EncodeToString(hash[:])
}
